# Output = input, with 3s replaced so the whole grid is 180-rotation-symmetric.
# In demo: O[r][c]=O[15-r][15-c] and all non-3 cells match I. So fill each 3-cell by its 180-mirror of a non-3 cell.
def f(I):
    A=[r[:] for r in I]; H=len(A)
    for r in range(H):
        for c in range(len(A[0])):
            if A[r][c]==3:
                A[r][c]=A[H-1-r][H-1-c] if I[H-1-r][H-1-c]!=3 else A[r][c]  # fallback
    return A
