# Fill all-3 regions consistently with surrounding pattern using reflection: treat unknown=3 as wildcard
I=G['Demo pair 1 input']; O=G['Demo pair 1 output']
def fill(A):
    H=len(A); W=len(A[0]); A=[r[:] for r in A]
    # repeatedly use any two equal-valued cells to complete
    for it in range(20):
        changed=False
        cells=[(r,c,A[r][c]) for r in range(H) for c in range(W)]
        for (r,c,v) in cells:
            for rr,cc in [(H-r,W-c),(r,W-c-1)]:
                if 0<=rr<H and 0<=cc<W:
                    if A[rr][cc]==v and A[rr][cc]!=3 and v!=3 and (rr,cc)!=(r,c):
                        continue
                    if A[rr][cc]!=3 and A[r][c]==3 and A[rr][cc]==v:
                        pass
                    if A[r][c]==3 and A[rr][cc] not in (3,v):
                        A[r][c]=A[rr][cc]; changed=True; break
                    elif A[rr][cc]==3 and A[r][c] not in (3,v):
                        A[rr][cc]=A[r][c]; changed=True; break
        if not changed: break
    return A
print(fill(I)==O)

# Fill the 3-blocks by copying the value from their vertical mirror positions (same row, mirrored column).
def fill(A):
    A=[r[:] for r in A]
    H=len(A)
    # first pass: use row mirror within each region? just do it.
    for it in range(10):
        changed=False
        for r in range(H):
            for c in range(len(A[0])):
                if A[r][c]==3:
                    mir=A[r][15-c]
                    if mir!=3: A[r][c]=mir; changed=True
        if not changed: break
    return A
